/* @author MILO-GAO(高振銘)@2020 */ package page2020.unit;import java.util.LinkedHashMap;import java.util.List;import java.util.Map;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import page2020.core.App;import page2020.core.Page;import page2020.util.EmptyUtil;import page2020.view.B4;import page2020.view.C3;import page2020.view.Content;import page2020.view.Element;import page2020.view.H5;import page2020.view.Text;import page2020.view.Value;import page2020.view.bs4.B4box;import page2020.view.bs4.B4collapse;import page2020.view.bs4.B4show.D;import page2020.view.bs4.B4text.TextX;import page2020.view.html5.H5a;import page2020.view.html5.H5span;public class Umenu extends B4box<Umenu> {	private static Logger log = LoggerFactory.getLogger(Umenu.class);	private static final String menu = "menu";	private static final String function = "func";	private static final String activeColor = "active";	private Map<String, Value[]> selectors = new LinkedHashMap<String, Value[]>();	private List<String> permission;	public Umenu() {		super();		super.name(PageKey.menu).p(1);		int count = App.menuProp.count();		for (int i=0; i < count; i++) {			Menu menuItem = App.menuProp.value(i);			if (menuItem.getLevel() == 0) {				this.menuItem(this, menuItem);			} else {				B4box<?> box = (B4box<?>) super.find(menu, menuItem.getParent());				if (box != null) {					this.menuItem(box, menuItem);				} else {					log.error("standard: '" + menuItem.getParent() + "' is NOT in messages.properties !");				}			}		}	}	public Umenu color(String color, String background, String active) {		super.css(C3.color(color), C3.bg(background));		super.data(activeColor, active);		String aE = "div[data-name='" + PageKey.menu + "'] a";		this.selectors.put(aE, new Value[] { C3.color(color), C3.margin("none") });		this.selectors.put(aE + ":link", new Value[] { C3.color(color) });		this.selectors.put(aE + ":visited", new Value[] { C3.color(color) });		this.selectors.put(aE + ":hover", new Value[] { C3.color(color), C3.text.decoration("none") });		this.selectors.put(aE + ":active", new Value[] { C3.color(color) });		return this;	}	public Umenu personal(List<String> permission) {		this.permission = permission;		int index = 0;		while (index < super.count()) {			Element<?, ?> element = (Element<?, ?>) super.get(index);			this.permission(element);			if (element.count() == 0) {				super.remove(index);			} else {				index += 1;			}		}		return this;	}	public Umenu selector(Page page) {		if (! this.selectors.isEmpty()) {			this.selectors.forEach((key, value) -> page.selector(key, value));		}		return this;	}	@Override	public Umenu copy() {		Umenu bean = (Umenu) super.copy();			bean.setSelectors(new LinkedHashMap<String, Value[]>(this.selectors));		return bean;	}	private void menuItem(B4box<?> box, Menu menuItem) {		B4collapse collapse = B4.collapse().ml(4).data(menu, menuItem.getName());		H5a a = collapse.a().cssClass(D.block, TextX.nowrap).append(			H5.span().append(App.icon("menu.close")),			H5.span().append(App.icon("menu.open")).cssClass(D.none),			H5.code(menuItem.getCode())		);		if (! menuItem.getFuncList().isEmpty()) {			int count = menuItem.getFuncList().size();			for (int i=0; i < count; i++) {				Func func = menuItem.getFuncList().get(i);				H5a link = H5.a().cssClass(D.block, TextX.nowrap)					.data(function, func.getName()).href(func.getAction());				Text icon = EmptyUtil.not(func.getIcon()) ? H5.icon(func.getIcon()) : App.icon("menu.link");				H5span span = H5.span().code(func.getCode());				collapse.append(link.append(icon, span));			}		}		box.append(a, collapse);	}	private void permission(Element<?, ?> parent) {		int index = 0;		while (index < parent.count()) {			Content<?> c = parent.get(index);			if (c instanceof H5a) {				H5a a = (H5a) c;				String name = (String) a.getData(function);				if (EmptyUtil.not(name) && (! this.permission.contains(name))) {					parent.remove(index);						continue;				}			} else if (c instanceof B4collapse) {				B4collapse collapse = (B4collapse) c;				this.permission(collapse);				if (collapse.count() == 0) {					parent.remove((--index));						parent.remove(index);							continue;				}			}			index += 1;		}	}	public Map<String, Value[]> getSelectors() {		return selectors;	}	public void setSelectors(Map<String, Value[]> selectors) {		this.selectors = selectors;	}}